mapper.select:
SELECT CONVERT(VARCHAR(4), T.UPTIME, 120) AS YEAR, T.EQUIPTCATEGORY, SUM(T.AMOUNT) AS AMOUNT FROM T_CORE_EQUIPT_USAGE_RECORD T WHERE T.UPTIME BETWEEN CONVERT (DATETIME, #{startYear}, 120) AND CONVERT (DATETIME, #{endYear}, 120)
AND T.EQUIPTCATEGORY = #{equiptCategory}
GROUP BY T.EQUIPTCATEGORY, CONVERT(VARCHAR(4), T.UPTIME, 120)
